// Real GPU test of the actual XR-owner component. Authored input, no XR session.
#define VK_NO_PROTOTYPES
#include "depth_pair_gpu_fixture.h"
#include "xr_gpu_scene_source.h"
#include <chrono>
#include <iostream>
namespace mkwvk {namespace {struct Bridge {bool reproject_capable=true;PFN_vkGetInstanceProcAddr vulkan_get=nullptr;};}
std::shared_ptr<const XrGpuSceneSource> smoke_packet;
std::shared_ptr<const XrGpuSceneSource> xr_gpu_scene_source_acquire(VkDevice,uint64_t,int64_t,bool,bool){return smoke_packet;}}
#include "vk_xr_gpu_late_pair.h"
using namespace hookshot::vr;using namespace hookshot::vr::smoke;
int64_t now(){return std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now().time_since_epoch()).count();}
uint32_t word(float f){uint32_t n;std::memcpy(&n,&f,4);return n;}
DepthPairParameters camera(unsigned eye,unsigned round){DepthPairParameters p;p.source_from_eye={1,0,0,(eye?.032f:-.032f)+round*.02f,0,1,0,0,0,0,1,0};p.eye_tangents={-1,1,1,-1};p.projection={.8f,.8f,-1.020202f,-.2020202f};p.optical={0,0,25000,.85f};p.dimensions={80,80,64,64};p.settings={123,8,1,8};return p;}
int main(int argc,char** argv){if(argc!=2||std::strcmp(argv[1],"--run")){std::cerr<<"Explicit offscreen GPU opt-in: --run\n";return 2;}
try{DepthPairGpuFixture fixture(80,80,64,64,true);auto& c=fixture.c;std::vector<uint32_t> source(12800);const auto base=camera(0,0);const float d=(1-base.projection[2]+base.projection[3]/2)/2;
 for(unsigned y=0;y<80;++y)for(unsigned x=0;x<80;++x){unsigned i=y*80+x;source[i]=x*4|(y*4<<9)|(128u<<18)|(15u<<27);source[6400+i]=word(d);}
 auto initial=fixture.run(source,{camera(0,0),camera(1,0)},1);require(initial.source==source,"fixture source unchanged");mkwvk::Bridge bridge;bridge.vulkan_get=c.get;mkwvk::GpuLatePair job;require(job.initialize(bridge,c.instance,fixture.gpu.physical,c.device,fixture.gpu.family,64,64),"initialize actual XR-owned GPU allocation/pipeline");
 auto packet=std::make_shared<mkwvk::XrGpuSceneSource>();packet->device=c.device;packet->buffer=c.auxiliary[0].buffer;packet->address=c.auxiliary[0].address;packet->bytes=51200;packet->state=1;packet->generation=7;packet->recording=1;packet->width=packet->height=80;packet->queue_family=fixture.gpu.family;packet->format=123;packet->pose.valid=true;packet->pose.generation=1;packet->pose.observed_ns=now();packet->ready_ns=packet->pose.observed_ns;packet->projection[0]=packet->projection[5]=.8f;packet->projection[10]=base.projection[2];packet->projection[11]=base.projection[3];mkwvk::smoke_packet=packet;
 std::vector<uint32_t> previous;unsigned changed=0;
 for(unsigned round=0;round<2;++round){DepthPairTrackingTarget target;target.origin=1;target.serial=round+1;target.observed_ns=now();for(unsigned eye=0;eye<2;++eye){auto& e=target.eyes[eye];e.orientation_valid=e.position_valid=true;e.position[0]=(eye?.032f:-.032f)+round*.02f;e.fov={-float(std::atan(1)),float(std::atan(1)),float(std::atan(1)),-float(std::atan(1))};}
  require(job.prepare(target,now()),"prepare current XR pose using the same completed source");checked(c.fn<PFN_vkResetCommandPool>("vkResetCommandPool")(c.device,c.pool,0),"reset completed command pool");VkCommandBufferBeginInfo begin{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};checked(c.fn<PFN_vkBeginCommandBuffer>("vkBeginCommandBuffer")(fixture.command,&begin),"begin owner job");require(job.record(fixture.command),"record actual owner dispatch pair");
  fixture.order(VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_SHADER_WRITE_BIT,VK_ACCESS_TRANSFER_READ_BIT);VkBufferCopy copy{0,0,job.bytes};c.fn<PFN_vkCmdCopyBuffer>("vkCmdCopyBuffer")(fixture.command,job.buffer,c.staging,1,&copy);fixture.order(VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_HOST_BIT,VK_ACCESS_TRANSFER_WRITE_BIT,VK_ACCESS_HOST_READ_BIT);checked(c.fn<PFN_vkEndCommandBuffer>("vkEndCommandBuffer")(fixture.command),"end owner job");
  VkFence fence;VkFenceCreateInfo fi{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};checked(c.fn<PFN_vkCreateFence>("vkCreateFence")(c.device,&fi,nullptr,&fence),"create owner test fence");VkSubmitInfo si{VK_STRUCTURE_TYPE_SUBMIT_INFO};si.commandBufferCount=1;si.pCommandBuffers=&fixture.command;c.uncertain=true;checked(c.fn<PFN_vkQueueSubmit>("vkQueueSubmit")(c.queue,1,&si,fence),"submit owner test");checked(c.fn<PFN_vkWaitForFences>("vkWaitForFences")(c.device,1,&fence,VK_TRUE,5000000000ull),"complete owner test");c.uncertain=false;c.fn<PFN_vkDestroyFence>("vkDestroyFence")(c.device,fence,nullptr);
  auto metadata=job.completed(now());require(metadata.complete&&metadata.target.serial==round+1&&metadata.source_state==1&&metadata.target.eyes[0].position[0]==target.eyes[0].position[0],"metadata preserves actual new render pose and common source identity");void* mapped;checked(c.fn<PFN_vkMapMemory>("vkMapMemory")(c.device,c.memory,0,VK_WHOLE_SIZE,0,&mapped),"map completed test output");if(!fixture.coherent){VkMappedMemoryRange mr{VK_STRUCTURE_TYPE_MAPPED_MEMORY_RANGE};mr.memory=c.memory;mr.size=VK_WHOLE_SIZE;checked(c.fn<PFN_vkInvalidateMappedMemoryRanges>("vkInvalidateMappedMemoryRanges")(c.device,1,&mr),"invalidate test output");}std::vector<uint32_t> output(job.bytes/4);std::memcpy(output.data(),mapped,job.bytes);c.fn<PFN_vkUnmapMemory>("vkUnmapMemory")(c.device,c.memory);job.discard();
  auto reference=fixture.run(source,{camera(0,round),camera(1,round)},round+2);require(reference.source==source,"source GPU packet unchanged after owner use");for(unsigned eye=0;eye<2;++eye)for(unsigned y=0;y<64;++y)for(unsigned x=0;x<64;++x)require(output[eye*4096+y*64+x]==reference.pixels[y*128+eye*64+x],"actual owner GPU pixels match independent camera/fixture result");if(round)for(unsigned i=0;i<output.size();++i)changed+=output[i]!=previous[i];previous=std::move(output);
 }
 require(changed>1000,"new view sample really changes GPU eye pixels for the same source");require(job.state==2,"both owner jobs recorded");job.close();mkwvk::smoke_packet.reset();std::cout<<"actual_XR_owner_GPU=true; authored_source_unchanged=true; same_source_state=1; fresh_pose_jobs=2; changed_pixels="<<changed<<"; checked_pixels=16384; XR_session=false; game=false\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
